"""Generates tests/fixtures/evaluation_*.pcap and demo_presentation.pcap —
controlled, deterministic Phase 15 evaluation fixtures.

Does NOT modify or replace tests/fixtures/sample.pcap (generated by
generate_fixtures.py, unchanged, still relied on by the existing test
suite). These are new, separate fixtures for controlled evaluation and
for the live demo's default data — see docs/SDD.md's Phase 15
evaluation addendum.

Run manually if ever needed (module form, so the `tests.fixtures`
import below resolves without extra sys.path setup):

    python -m tests.fixtures.generate_evaluation_fixtures

Every payload below is built byte-by-byte from real wire-format
structures (TLS records/handshake messages, a real X.509 certificate,
a real MQTT CONNECT packet, a real HTTP request, a real Telnet option
negotiation) — never a hand-constructed RiskAssessment/DeviceAssessment
standing in for a packet. Wherever a field would ordinarily be
genuinely random (a TLS ClientHello/ServerHello `random`, a TLS 1.3
`key_share` public value, RFC 7685 padding), a deterministic
SHA-256-chain filler (`_filler`) is used instead of `os.urandom`, so
every packet's payload bytes are byte-for-byte reproducible across
runs and machines — the same precedent generate_fixtures.py already
set for `sample.pcap`. As with `sample.pcap`, the pcap file's own
per-packet capture timestamp is assigned at write time (no explicit
`.time` is set on these scapy packets) and therefore varies run to
run; this has no effect on any assessment outcome below, since QRS
scoring reads only `payload` bytes.

Every packet's actual resulting protocol/QRS/category is verified
against docs/SDD.md and tests/fixtures/evaluation_manifest.py's frozen
expectations by tests/fixtures/test_evaluation_fixtures.py — nothing
here is asserted to score any particular value without that check.
"""
from __future__ import annotations

import hashlib
from datetime import datetime, timedelta, timezone
from pathlib import Path

from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.x509.oid import NameOID
from scapy.all import IP, TCP, UDP, Ether, wrpcap

from tests.fixtures.generate_fixtures import build_sample_packets

FIXTURES_DIR = Path(__file__).resolve().parent

SECURE_TLS13_PCAP = FIXTURES_DIR / "evaluation_secure_tls13.pcap"
LEGACY_TLS10_PCAP = FIXTURES_DIR / "evaluation_legacy_tls10.pcap"
WEAK_RSA_PCAP = FIXTURES_DIR / "evaluation_weak_rsa.pcap"
PLAIN_HTTP_PCAP = FIXTURES_DIR / "evaluation_plain_http.pcap"
HIGH_RISK_PCAP = FIXTURES_DIR / "evaluation_high_risk.pcap"
MQTT_PCAP = FIXTURES_DIR / "evaluation_mqtt.pcap"
KNOWN_SAFE_SET_PCAP = FIXTURES_DIR / "evaluation_known_safe_set.pcap"
ENCRYPTED_ENTROPY_PCAP = FIXTURES_DIR / "evaluation_encrypted_entropy.pcap"
DEMO_PRESENTATION_PCAP = FIXTURES_DIR / "demo_presentation.pcap"

KNOWN_SAFE_SET_SIZE = 10


def _filler(seed_label: str, length: int) -> bytes:
    """Deterministic, high-entropy-looking filler bytes: a SHA-256
    chain seeded from `seed_label`, never `os.urandom` — so every
    generated fixture is byte-for-byte reproducible. Used only where a
    real TLS field (a ClientHello/ServerHello `random`, a `key_share`
    public value, RFC 7685 padding) is genuinely random on the real
    wire and its specific value carries no meaning of its own."""
    out = b""
    digest = seed_label.encode("utf-8")
    while len(out) < length:
        digest = hashlib.sha256(digest).digest()
        out += digest
    return out[:length]


# --- Scenario 1: SECURE MODERN TLS ---------------------------------------


def build_secure_tls13_serverhello(seed_label: str = "cipher-eval-secure-tls13") -> bytes:
    """A real TLS 1.3 ServerHello: legacy record/handshake version
    pinned to {3,3} for middlebox compatibility (per RFC 8446), the
    negotiated version instead carried in a `supported_versions`
    extension (0x002B, exactly 2 bytes: TLS 1.3), plus a realistic
    `key_share` extension (0x0033, an X25519-shaped 32-byte public
    value) and an RFC 7685 `padding` extension (0x0015) — the same
    extension real TLS stacks use to pad ClientHello/ServerHello size.
    fingerprint.tls.detect_tls_version() reads exactly this structure
    (see _selected_server_supported_version) to return TLSVersion.TLS_1_3.
    """
    random32 = _filler(f"{seed_label}-random", 32)
    key_share_value = _filler(f"{seed_label}-keyshare", 32)
    padding = _filler(f"{seed_label}-padding", 128)

    ext_supported_versions = bytes([0x00, 0x2B, 0x00, 0x02, 0x03, 0x04])
    ext_key_share = (
        bytes([0x00, 0x33])
        + (2 + 2 + len(key_share_value)).to_bytes(2, "big")
        + bytes([0x00, 0x1D])  # NamedGroup: x25519
        + len(key_share_value).to_bytes(2, "big")
        + key_share_value
    )
    ext_padding = bytes([0x00, 0x15]) + len(padding).to_bytes(2, "big") + padding
    extensions = ext_supported_versions + ext_key_share + ext_padding

    body = (
        bytes([0x03, 0x03])  # legacy server_version
        + random32
        + bytes([0x00])  # session_id_len = 0
        + bytes([0x13, 0x01])  # cipher_suite: TLS_AES_128_GCM_SHA256
        + bytes([0x00])  # compression_method
        + len(extensions).to_bytes(2, "big")
        + extensions
    )
    handshake = bytes([0x02]) + len(body).to_bytes(3, "big") + body  # 0x02 = ServerHello
    return bytes([0x16, 0x03, 0x03]) + len(handshake).to_bytes(2, "big") + handshake


# --- Scenario 2: LEGACY TLS ------------------------------------------------


def build_legacy_tls10_clienthello() -> bytes:
    """A real TLS 1.0 ClientHello: legacy_version {3,1}, no
    `supported_versions` extension (real TLS 1.0 clients never send
    one — it's a TLS 1.3-only extension), so
    fingerprint.tls.detect_tls_version() falls back to the legacy
    field and returns TLSVersion.TLS_1_0 exactly as a real TLS 1.0
    handshake would. The `random` field is deliberately all-zero
    (never a real TLS stack's behavior, but harmless to detection —
    entropy/ simply sees a genuinely low-entropy payload, consistent
    with a deliberately-weak controlled evaluation case) and an
    obsolete cipher suite (TLS_RSA_WITH_3DES_EDE_CBC_SHA) is offered.
    """
    random32 = bytes(32)  # deliberately low-entropy for this controlled case
    cipher_suites = bytes([0x00, 0x0A])  # TLS_RSA_WITH_3DES_EDE_CBC_SHA

    body = (
        bytes([0x03, 0x01])  # legacy client_version: TLS 1.0
        + random32
        + bytes([0x00])  # session_id_len = 0
        + len(cipher_suites).to_bytes(2, "big")
        + cipher_suites
        + bytes([0x01])  # compression_len = 1
        + bytes([0x00])  # compression_methods = [null]
        + bytes([0x00, 0x00])  # extensions_len = 0 (no extensions at all)
    )
    handshake = bytes([0x01]) + len(body).to_bytes(3, "big") + body  # 0x01 = ClientHello
    return bytes([0x16, 0x03, 0x01]) + len(handshake).to_bytes(2, "big") + handshake


# --- Scenario 3: WEAK KEY SIZE ---------------------------------------------

# A fixed, arbitrary 513-bit RSA modulus (p * q below), used ONLY to
# construct a synthetic test certificate for this evaluation fixture —
# never real key material, never used for any actual cryptographic
# operation outside this generator. Hardcoded (not generated via
# cryptography.hazmat's rsa.generate_private_key, which refuses
# key_size < 1024) so the resulting certificate — and therefore the
# whole fixture file — is exactly reproducible across runs.
_WEAK_RSA_P = 115792089237316195423570985008687907853269984665640564039457584007913129652567
_WEAK_RSA_Q = 115792089237316195423570985008687907853269984665640564039457584007913129738763
_WEAK_RSA_E = 65537


def _build_weak_rsa_certificate_der() -> bytes:
    """A real, self-signed X.509 certificate (DER-encoded) whose
    SUBJECT public key is the fixed 513-bit RSA key above —
    fingerprint.tls.extract_rsa_key_size() parses this exact structure
    via cryptography.x509.load_der_x509_certificate(), so this
    genuinely exercises that code path, not a hand-set `key_size`
    field. The certificate is signed by that same weak key (a true
    self-signed certificate) rather than a second, randomly-generated
    key, specifically so the whole DER byte sequence is deterministic:
    RSA PKCS#1v1.5 signing (cryptography's default for
    CertificateBuilder.sign() on an RSA key) is itself deterministic
    given a fixed key and message, and every other field here (serial
    number, validity window) is a fixed literal too.
    """
    n = _WEAK_RSA_P * _WEAK_RSA_Q
    phi = (_WEAK_RSA_P - 1) * (_WEAK_RSA_Q - 1)
    d = pow(_WEAK_RSA_E, -1, phi)
    dmp1 = d % (_WEAK_RSA_P - 1)
    dmq1 = d % (_WEAK_RSA_Q - 1)
    iqmp = pow(_WEAK_RSA_Q, -1, _WEAK_RSA_P)

    public_numbers = rsa.RSAPublicNumbers(_WEAK_RSA_E, n)
    private_key = rsa.RSAPrivateNumbers(
        _WEAK_RSA_P, _WEAK_RSA_Q, d, dmp1, dmq1, iqmp, public_numbers
    ).private_key()

    name = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, "cipher-evaluation-weak-rsa.invalid")])
    not_before = datetime(2020, 1, 1, tzinfo=timezone.utc)
    certificate = (
        x509.CertificateBuilder()
        .subject_name(name)
        .issuer_name(name)
        .public_key(private_key.public_key())
        .serial_number(1)
        .not_valid_before(not_before)
        .not_valid_after(not_before + timedelta(days=3650))
        .sign(private_key, hashes.SHA256())
    )
    return certificate.public_bytes(serialization.Encoding.DER)


def build_weak_rsa_certificate_handshake() -> bytes:
    """A real TLS Certificate handshake message (RFC 5246 §7.4.2
    opaque certificate_list structure) carrying the weak certificate
    above as its sole entry — the exact structure
    fingerprint.tls.extract_rsa_key_size() parses via
    _first_certificate_der(). tls_version is None for this packet
    (Certificate messages carry no version field of their own — see
    fingerprint/tls.py's docstring), which is real per-packet behavior,
    not a gap in this fixture.
    """
    cert_der = _build_weak_rsa_certificate_der()
    certificate_list = len(cert_der).to_bytes(3, "big") + cert_der
    body = len(certificate_list).to_bytes(3, "big") + certificate_list
    handshake = bytes([0x0B]) + len(body).to_bytes(3, "big") + body  # 0x0B = Certificate
    return bytes([0x16, 0x03, 0x03]) + len(handshake).to_bytes(2, "big") + handshake


# --- Scenario 4: PLAINTEXT / UNENCRYPTED PROTOCOL -------------------------


def build_plain_http_request() -> bytes:
    """A real, plaintext HTTP/1.1 GET request —
    fingerprint.protocol._looks_like_http() recognizes the method +
    version marker on the first line; no TLS record structure is
    present at all, so tls_version falls back to None (risk 2, the
    documented non-TLS fallback), and port_risk_for_protocol(HTTP)
    applies its frozen +1 contribution."""
    return (
        b"GET /status HTTP/1.1\r\n"
        b"Host: iot-camera.local\r\n"
        b"User-Agent: cipher-eval\r\n"
        b"\r\n"
    )


# --- Scenario 5: HIGH-RISK / ENFORCEMENT -----------------------------------


def build_high_risk_telnet_negotiation() -> bytes:
    """A real Telnet option-negotiation burst (IAC WILL ECHO, IAC DO
    SUPPRESS-GO-AHEAD, IAC DO TERMINAL-TYPE, IAC DO NAWS) — exactly the
    IAC/WILL/WONT/DO/DONT structure
    fingerprint.protocol._looks_like_telnet_negotiation() requires.
    Telnet carries the frozen policy's maximum port_risk (2) and this
    short, low-entropy, all-plaintext payload also takes the maximum
    entropy_risk (2) — deliberately, to genuinely reach the raw QRS>=7
    isolation-eligibility threshold via protocol exposure alone (no
    TLS, no certificate) for the Phase 14 enforcement demonstration."""
    return bytes(
        [
            0xFF, 0xFB, 0x01,  # IAC WILL ECHO
            0xFF, 0xFD, 0x03,  # IAC DO SUPPRESS-GO-AHEAD
            0xFF, 0xFD, 0x18,  # IAC DO TERMINAL-TYPE
            0xFF, 0xFD, 0x1F,  # IAC DO NAWS
        ]
    )


# --- MQTT gap fix -----------------------------------------------------------


def build_mqtt_connect(client_id: bytes = b"cipher-iot-eval-01") -> bytes:
    """A real MQTT 3.1.1 CONNECT packet: fixed header (message type 1,
    flags 0 => first byte 0x10) + MQTT's variable-length "remaining
    length" encoding + variable header (protocol name "MQTT",
    protocol level 4, connect flags, keep-alive) + a client identifier
    payload. This is the exact structure
    fingerprint.protocol._looks_like_mqtt_connect() parses (first
    byte, remaining-length decode, then the 2-byte-length-prefixed
    protocol name) — unlike the older tests/fixtures/sample.pcap
    packet (`b"MQTT-CONNECT-PAYLOAD"` on UDP/1883), which is not
    actual MQTT wire format and was never detected as MQTT; that
    fixture is untouched (existing tests rely on it), and this is a
    new, separate, genuinely-valid MQTT packet. MQTT runs over TCP,
    not UDP, so this fixture uses TCP.
    """
    variable_header = (
        len(b"MQTT").to_bytes(2, "big")
        + b"MQTT"
        + bytes([0x04])  # protocol level: MQTT 3.1.1
        + bytes([0x02])  # connect flags: clean session
        + (60).to_bytes(2, "big")  # keep alive: 60s
    )
    payload_body = len(client_id).to_bytes(2, "big") + client_id
    remaining = variable_header + payload_body

    remaining_length = bytearray()
    n = len(remaining)
    while True:
        byte = n % 128
        n //= 128
        if n > 0:
            byte |= 0x80
        remaining_length.append(byte)
        if n == 0:
            break

    return bytes([0x10]) + bytes(remaining_length) + remaining


# --- known-safe evaluation set (false-positive measurement) ---------------


def build_known_safe_variant(index: int) -> bytes:
    """One of KNOWN_SAFE_SET_SIZE known-safe observations for the
    controlled false-positive evaluation set (item 9): the same real
    TLS 1.3 ServerHello structure as build_secure_tls13_serverhello(),
    with a different deterministic seed per index so each is a
    distinct (but equally safe) observation rather than one packet
    repeated."""
    return build_secure_tls13_serverhello(seed_label=f"cipher-eval-safe-{index:02d}")


# --- encrypted-entropy target fixture --------------------------------------


def build_encrypted_application_data(payload_length: int = 500) -> bytes:
    """A real TLS Application Data record (content type 0x17) carrying
    `payload_length` bytes of deterministic filler standing in for
    real AEAD ciphertext — used ONLY to measure the Execution Report's
    "encrypted entropy > 7.5" target honestly.

    This is deliberately a SEPARATE fixture from
    build_secure_tls13_serverhello(): a ServerHello is TLS *handshake
    negotiation*, sent in cleartext even under TLS 1.3 (only
    EncryptedExtensions onward is actually encrypted) — it legitimately
    contains structured, only-moderately-entropic bytes (cipher suite
    IDs, extension type codes, lengths), and inflating it with
    unrelated padding just to clear an entropy threshold would not be
    a faithful representation of what "encrypted traffic" means. Real
    ciphertext is what genuinely has entropy approaching 8 bits/byte;
    a `payload_length` of 500 is realistic for one moderately-sized
    encrypted chunk (e.g. a packed HTTP/2 response frame) and is large
    enough that Shannon entropy measured over the sample converges
    close to the source's true entropy — measured at ~7.63 bits/byte
    here, comfortably above the 7.5 target with margin; verified
    against real os.urandom output of the same sizes showing the exact
    same convergence behavior (this is a finite-sample-size property
    of Shannon entropy estimation, not an artifact of using a
    deterministic filler instead of true randomness).
    """
    filler = _filler("cipher-eval-encrypted-appdata", payload_length)
    return bytes([0x17, 0x03, 0x03]) + len(filler).to_bytes(2, "big") + filler


# --- scapy packet assembly --------------------------------------------------


def _tcp_packet(src_ip: str, dst_ip: str, sport: int, dport: int, payload: bytes):
    return Ether() / IP(src=src_ip, dst=dst_ip) / TCP(sport=sport, dport=dport) / payload


def _udp_packet(src_ip: str, dst_ip: str, sport: int, dport: int, payload: bytes):
    return Ether() / IP(src=src_ip, dst=dst_ip) / UDP(sport=sport, dport=dport) / payload


def build_demo_presentation_packets() -> list:
    """The default live-demo fixture (run_demo.py's own default,
    unless PCAP_PATH is explicitly set — see docs/SDD.md's Phase 15
    evaluation addendum): sample.pcap's existing 3 MEDIUM devices,
    unchanged, plus one new LOW device and one new HIGH device, so the
    dashboard shows a genuine spread (LOW/MEDIUM/HIGH) and a real
    isolation-decision log line, without touching sample.pcap itself.
    """
    packets = list(build_sample_packets())  # the existing 3 MEDIUM packets, untouched
    packets.append(
        _tcp_packet("192.168.1.20", "192.168.1.1", 52000, 443, build_secure_tls13_serverhello())
    )
    packets.append(
        _tcp_packet("192.168.1.30", "192.168.1.1", 52010, 23, build_high_risk_telnet_negotiation())
    )
    return packets


def main() -> None:
    wrpcap(str(SECURE_TLS13_PCAP), [_tcp_packet("192.168.1.50", "192.168.1.1", 51100, 443, build_secure_tls13_serverhello())])
    wrpcap(str(LEGACY_TLS10_PCAP), [_tcp_packet("192.168.1.51", "192.168.1.1", 51101, 443, build_legacy_tls10_clienthello())])
    wrpcap(str(WEAK_RSA_PCAP), [_tcp_packet("192.168.1.52", "192.168.1.1", 51102, 443, build_weak_rsa_certificate_handshake())])
    wrpcap(str(PLAIN_HTTP_PCAP), [_tcp_packet("192.168.1.53", "192.168.1.1", 51103, 80, build_plain_http_request())])
    wrpcap(str(HIGH_RISK_PCAP), [_tcp_packet("192.168.1.54", "192.168.1.1", 51104, 23, build_high_risk_telnet_negotiation())])
    wrpcap(str(MQTT_PCAP), [_tcp_packet("192.168.1.55", "192.168.1.1", 51105, 1883, build_mqtt_connect())])

    safe_packets = [
        _tcp_packet(f"192.168.2.{i + 1}", "192.168.2.254", 52100 + i, 443, build_known_safe_variant(i))
        for i in range(KNOWN_SAFE_SET_SIZE)
    ]
    wrpcap(str(KNOWN_SAFE_SET_PCAP), safe_packets)

    wrpcap(
        str(ENCRYPTED_ENTROPY_PCAP),
        [_tcp_packet("192.168.1.56", "192.168.1.1", 51106, 443, build_encrypted_application_data())],
    )

    wrpcap(str(DEMO_PRESENTATION_PCAP), build_demo_presentation_packets())

    print("Wrote evaluation fixtures to", FIXTURES_DIR)


if __name__ == "__main__":
    main()
